class Solution:
    def maximumSumOfHeights(self, heights: List[int]) -> int:
        n = len(heights); ans = 0
        for i in range(n):
            total = heights[i]
            cap = heights[i]
            for j in range(i - 1, -1, -1):
                cap = min(cap, heights[j])
                total += cap
            cap = heights[i]
            for j in range(i + 1, n):
                cap = min(cap, heights[j])
                total += cap
            ans = max(ans, total)
        return ans

