        for (int i = 0; i < n; i++) {
            long long total = heights[i];
            long long cap = heights[i];
            for (int j = i - 1; j >= 0; j--) { cap = min(cap, (long long)heights[j]); total += cap; }
            cap = heights[i];
            for (int j = i + 1; j < n; j++) { cap = min(cap, (long long)heights[j]); total += cap; }
            ans = max(ans, total);
        }
        return ans;
    }
};

