class Solution:
    def maximumSumOfHeights(self, heights: List[int]) -> int:
        n = len(heights)
        def calc(h):
            st = []  # [height, count]
            total = 0
            res = []
            for x in h:
                cnt = 1
                while st and st[-1][0] >= x:
                    hh, c = st.pop()
                    total -= hh * c
                    cnt += c
                st.append([x, cnt])
                total += x * cnt
                res.append(total)
            return res
        L = calc(heights)
        R = calc(heights[::-1])[::-1]
        return max(L[i] + R[i] - heights[i] for i in range(n))

