class Solution {
    vector<long long> calc(vector<int>& h) {
        int n = h.size();
        vector<pair<long long,long long>> st;
        long long total = 0;
        vector<long long> res(n);
        for (int i = 0; i < n; i++) {
            long long x = h[i], cnt = 1;
            while (!st.empty() && st.back().first >= x) {
                total -= st.back().first * st.back().second;
                cnt += st.back().second;
                st.pop_back();
            }
            st.push_back({x, cnt});
            total += x * cnt;
            res[i] = total;
        }
        return res;
    }
public:
    long long maximumSumOfHeights(vector<int>& heights) {
        int n = heights.size();
        vector<long long> L = calc(heights);
        reverse(heights.begin(), heights.end());
        vector<long long> Rv = calc(heights);
        reverse(Rv.begin(), Rv.end());
        reverse(heights.begin(), heights.end());
        long long ans = 0;
        for (int i = 0; i < n; i++) ans = max(ans, L[i] + Rv[i] - heights[i]);
        return ans;
    }
};

