class Solution {
    long[] calc(List<Integer> h) {
        int n = h.size();
        ArrayDeque<long[]> st = new ArrayDeque<>();
        long total = 0;
        long[] res = new long[n];
        for (int i = 0; i < n; i++) {
            long x = h.get(i), cnt = 1;
            while (!st.isEmpty() && st.peek()[0] >= x) {
                long[] seg = st.pop();
                total -= seg[0] * seg[1];
                cnt += seg[1];
            }
            st.push(new long[]{x, cnt});
            total += x * cnt;
            res[i] = total;
        }
        return res;
    }
    public long maximumSumOfHeights(List<Integer> heights) {
        int n = heights.size();
        long[] L = calc(heights);
        java.util.Collections.reverse(heights);
        long[] R = calc(heights);
        long ans = 0;
        for (int i = 0; i < n; i++) ans = Math.max(ans, L[i] + R[n - 1 - i] - heights.get(n - 1 - i));
        return ans;
    }
}

