    const calc = (h) => {
        const st = [];
        let total = 0;
        const res = [];
        for (const x of h) {
            let cnt = 1;
            while (st.length && st[st.length - 1][0] >= x) {
                const [hh, c] = st.pop();
                total -= hh * c;
                cnt += c;
            }
            st.push([x, cnt]);
            total += x * cnt;
            res.push(total);
        }
        return res;
    };
    const L = calc(heights);
    const R = calc(heights.slice().reverse()).reverse();
    let ans = 0;
    for (let i = 0; i < n; i++) ans = Math.max(ans, L[i] + R[i] - heights[i]);
    return ans;
};
